/** What kind of operation the state performs on the message. As with CodonKind, the lane draws from this and never
 *  from the state name, so the two skip cells are one function. */
export type TranscriptKind =
  | "establishing" /** no operation: the message end to end, position and scale */
  | "foreclosed" /** a cut site is damaged and which repair follows is unmeasured */
  | "skip" /** a block is bypassed and the seam closes over it */
  | "retain" /** a seam fails to close and intron material rides in */
  | "pseudo-exon" /** a cut site is manufactured and a false block splices in */
  | "double-agent" /** one base that both spells and signs */
  | "dosage" /** the unit is the whole gene */
  | "whole-gene" /** O5: this copy of the gene is deleted outright */
  | "copies"; /** a change in how many copies of the gene you have: one row per copy */

/** Material that arrived and is not in the reference (the retained stretch, or the false block): how much, out of
 *  which gap, and whether reading survives it are facts that travel together. */
export interface Admitted {
  /** the coding position the material arrives after */
  afterC: number;
  /** how much of it there is */
  nt: number;
  /** which gap it came out of, and how big that gap is */
  intron: number;
  intronBp: number;
  /** where inside that intron it sits, as HGVS offsets — positive counting in
   *  from the donor, negative counting back from the acceptor */
  fromOffset: number;
  toOffset: number;
  /** does the arriving length leave the reading frame intact */
  inFrame: boolean;
  /** 1-based nucleotide inside this material at which reading stops, or null if reading passes through it. The two
   *  cells that admit material differ on exactly this, so it is a field and not a rule. */
  stopWithinNt: number | null;
}

export interface TranscriptSpecimen {
  id: string;
  gene: string;
  variant: string;
  clinvar: string;
  transcript: string;
  reviewStatus: string;
  reviewStars: number;
  kind: TranscriptKind;
  /** the variant's address. `locusC` is a coding position and `locusOffset` is
   *  the HGVS intronic offset from it: 0 = the variant is in the block itself,
   *  positive = it is that many bases into the following gap, negative = that
   *  many back from the next block's edge. */
  locusC: number | null;
  locusOffset: number;
  /** the junction the cell is about: the last coding base before the gap */
  junctionC: number | null;
  /** skip only — the bypassed block, in coding coordinates */
  skipLo: number | null;
  skipHi: number | null;
  skipBp: number | null;
  /** does the message survive this with its frame intact */
  inFrame: boolean | null;
  admitted: Admitted | null;
  /** where reading stops, in codons, and the same stop in original transcript coordinates, so the register can place
   *  it at a reference address and then apply the beat's displacement. Null where the stop is inside admitted
   *  material, which has no reference address. */
  stopCodon: number | null;
  stopNtRef: number | null;
  proteinAa: number | null;
  /** dosage only */
  copies: number | null;
  spanBp: number | null;
  /** "copies" only: how many copies there were before the change (default 2) */
  copiesFrom?: number;
  consequence: string;
  /** the gene's own pieces: coding blocks in transcript order, cumulative coding coordinates, and the CDS length.
   *  Absent on the 7 built cells, which are BRCA1 and read BRCA1_EXONS; a variant brings its own. */
  exons?: readonly { exon: number; cLo: number; cHi: number; bp: number }[];
  cdsLength?: number;
  /** all the gene's exons, coding or not, for the caption's "OF N" */
  exonCount?: number;
  /** O1's junction close-up. Present, the transcript lane draws the join at letter scale in one of three states
   *  instead of the block-scale foreclosure. */
  junction?: {
    side: "donor" | "acceptor";
    /** the cut signal's letters each side of the join, from the facts (the facts stage's SIGNAL);
     *  the bracket draws exactly this, so it can't disagree with the routing */
    window: { exon: number; intron: number };
    offsets: readonly number[];
    state: "broken" | "weakened" | "beside";
    phase: number;
    edit: "sub" | "del" | "dup" | "ins" | "delins";
  };
}

