/* ---- The portrait lane ---- */

export interface FoldSpecimen {
  id: string;
  gene: string;
  uniprot: string;
  /** the whole protein's length, for the locator (O2) */
  length?: number;
  /** residue range of the window, inclusive, 1-based on the chain */
  start: number;
  end: number;
  /** index into points[] of the marked residue */
  markIdx: number;
  /** the projection: one 2D point per residue on the window's own first two principal axes, computed once in the
   *  generator and frozen here, so a lane can't re-derive a plane and move its anchor. */
  points: readonly (readonly number[])[];
  /** per-residue pLDDT over the window. A module's register is its own confidence, not the window's mean, or a
   *  half-confident window and an empty one render identically. */
  plddt: readonly number[];
  /** indices into `points` the marked residue touches: Cα within `contactMaxA` and at least `contactMinSep` apart in
   *  sequence, which makes the list a fact about this position rather than about the backbone. */
  contacts: readonly number[];
  /** explained variance of all three principal axes. The first two are drawn; the third is how much of the object
   *  the drawing throws away, kept so the portrait can say so. */
  evr: readonly number[];
  source: string;
  /** stop-loss-extension only: residues the extension runs for (terminator − true end). Absent on the built cell,
   *  which reads it from the codon lane's PALB2 record (frames.ts FOLD_EXT); a variant brings its own. */
  extension?: number;
  /** sealed-removal only: residues removed from markIdx on (default 1). A
   *  variant brings its own; the built cell removes one. */
  removed?: number;
  /** insertion-bulge only: residues that arrive after markIdx (default 1) */
  added?: number;
  /** E2: a run of changed residues (window indices). With it, `contacts` is the run's one set and `contactFrom[k]`
   *  the index into `marks` each is drawn from. */
  marks?: readonly number[];
  contactFrom?: readonly number[];
  /** O4: buried (no words), on the surface at an annotated site (`partners`, plain names), or on the surface with
   *  nothing annotated. Absent on the built cells, which draw no words. */
  o4?: { state: "buried" | "surface-site" | "surface"; cn?: number; partners?: readonly string[] };
}

