/** What the one silent cell says: a finding, one mono label, and no other stage carries copy (RULES.md §2.12).
 *  `absent` is a measured result (BRCA1 R1443X makes no protein), not a drawing that failed. A stage never explains
 *  its own emptiness; sourcing belongs in an apparatus caption (`FOLD_REFUSAL.source`). Copy and its line breaks live
 *  here, not in markup, so they can't drift from what ships; an empty string is a blank line. */
export const FOLD_STATEMENTS: Record<string, readonly string[]> = {
  absent: ["No protein made."], // sentence case
};

export interface ChainSpecimen {
  id: string;
  gene: string;
  uniprot: string | null;
  /** the reference extent: how long the protein is supposed to be, which for `truncated` is not how long it is.
   *  `at()` scales over this, so a chain that ends early ends early on the page, at true proportion. */
  length: number;
  /** the residue the variant sits on */
  site: number;
  /** per-residue pLDDT end to end: the claim is the whole chain's profile. Empty where `unmapped`. */
  plddt: readonly number[];
  /** No structure map exists anywhere along this chain, so the whole register is let-go. Set on BRCA2 alone (no
   *  AlphaFold model; its 5.4% experimental coverage is short peptides inside other proteins' structures). A flag
   *  rather than an all-zero profile, because zero pLDDT is a measurement and this is the absence of one. */
  unmapped?: boolean;
  /** where the chain actually ends, when that is not `length`; absent otherwise, since the field exists to be the
   *  difference */
  lastResidue?: number;
  /** a run-on past the protein's end, in residues, for a protein with no confident fold at its end: the line scales
   *  to length + run-on, the reference end is ticked, and the run-on is drawn let-go in the variant's ink. */
  extension?: number;
  source: string;
}

